/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field MarkupGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTableModule, MarkupGroupId), tableStr(MarkupGroup), fieldStr(MarkupGroup, GroupId))]
internal class GUPPricingAttributeInventTableModuleSalesMarkupGroupId extends GUPPricingAttributeInventTableModuleSales implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Sales), fieldPName(InventTableModule, MarkupGroupId));
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTableModule   inventTableModule;
    MarkupGroup         markupGroup;
    InventTable         inventTable;

    while select MarkupGroupid from inventTableModule
        join markupGroup
        group by GroupId, Module, Txt
        where inventTableModule.MarkupGroupid == markupGroup.GroupId
            && markupGroup.Module == MarkupModuleType::Invent
            && InventTablemodule.ModuleType == ModuleInventPurchSales::Sales
        join ItemId from inventTable
        where inventTable.ItemId == inventTableModule.ItemId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(markupGroup.GroupId, markupGroup.Txt);
        ret.add(valueObject);
    }
    return ret;
}
